import{_ as i,a0 as r,w as n,s as a,ao as h,I as p,x as e,a1 as o,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux有问必答：如何在脚本中获取进程ID（PID） | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在脚本中获取进程ID（PID） | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在脚本中获取进程ID（PID） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在脚本中获取进程ID（PID） | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150209 Linux FAQs with Answers--How to get the process ID (PID) of a shell script","title":"Linux有问必答：如何在脚本中获取进程ID（PID）","tag":"201503","desc":""},"relativePath":"201503/20150209 Linux FAQs with Answers--How to get the process ID (PID) of a shell script.md","filePath":"[post].md"}'),D={name:"201503/20150209 Linux FAQs with Answers--How to get the process ID (PID) of a shell script.md"};function d(I,t,u,P,f,m){const s=r("Link");return n(),a("div",null,[t[11]||(t[11]=h(`<h1 id="linux有问必答-如何在脚本中获取进程id-pid" tabindex="-1">Linux有问必答：如何在脚本中获取进程ID（PID） <a class="header-anchor" href="#linux有问必答-如何在脚本中获取进程id-pid" aria-label="Permalink to “Linux有问必答：如何在脚本中获取进程ID（PID）”">​</a></h1><blockquote><p><strong>提问</strong>: 我想要知道运行中脚本子shell的进程id。我该如何在shell脚本中得到PID。</p></blockquote><p>当我在执行shell脚本时，它会启动一个叫子shell的进程。作为主shell的子进程，子shell将shell脚本中的命令作为批处理运行（因此称为“批处理进程”）。</p><p>在某些情况下，你也许想要知道运行中的子shell的PID。这个PID信息可以在不同的情况下使用。比如，你可以使用shell脚本的PID在/tmp下创建一个唯一的临时文件。有时侯脚本需要检测所有运行的进程，它可以从进程列表中排除自身的子shell。</p><p>在bash中，<strong>子shell进程的PID</strong>存储在一个特殊的变量‘$$’中。这个变量只读，你不可以在脚本中修改它。比如：</p><pre><code>#!/bin/bash
 
echo &quot;PID of this script: $$&quot;
</code></pre><p>上面的脚本会得到下面的输出：</p><pre><code>PID of this script: 6583
</code></pre><p>除了$$, bash shell还会导出其他的只读变量。比如，PPID存储子shell父进程的ID（也就是主shell）。UID存储了执行这个脚本的当前用户ID。比如：</p><pre><code>#!/bin/bash
 
echo &quot;PID of this script: $$&quot;
echo &quot;PPID of this script: $PPID&quot;
echo &quot;UID of this script: $UID&quot;
</code></pre><p>输出是：</p><pre><code>PID of this script: 6686
PPID of this script: 4656
UID of this script: 1000
</code></pre><p>上面输出中，PID每次执行都会变化。这个因为每次运行都会创建一个新的shell。另一方面，PPID每次都会一样只要你在同一个shell中运行。</p><p><img src="https://farm8.staticflickr.com/7437/16274890369_e78ce16d42_b.jpg" alt=""></p><p>对于所有bash内置变量列表，参考man页。</p><pre><code>$ man bash
</code></pre><hr>`,17)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(s,{href:"http://ask.xmodulo.com/process-id-pid-shell-script.html"},{default:l(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/process-id-pid-shell-script.html",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),o(s,{href:"http://linux.cn/"},{default:l(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const T=i(D,[["render",d]]);export{_ as __pageData,T as default};
